|target range = {{tip|cr|icononly = true}} {{tt|675|First cast range}}
|speed        = {{dv|{{tt|1500|Initial dash speed}}|{{tt|3000|Second dash speed}}}}
|collision radius= {{tip|er|icononly = true}} {{tt|110|Both casts dash collision, estimated}}
|cooldown     = {{ap|120 to 60}}
|cdstart      = post-effect
|cast time    = {{dv|{{tt|{{fd|0.25}}|Initial cast}}|{{tt|None|Recast}}}}
|queue time   = {{dv|{{tt|{{fd|0.5}}|Initial cast}}|{{tt|{{fd|0.3}}|Recast}}}}
|targeting    = {{dv|[[Unit-targeted|Unit]]|[[Direction-targeted|Direction]]}}
|affects      = Enemies
|damagetype   = Magic
